<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><title><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?> — Installment Plans</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?= $theme_link; ?>css/font-awesome-4.7.0/css/font-awesome.min.css"><style>:root{--p:#0057ff;--bg:#f1f5f9;--text:#0f172a;--muted:#64748b;--border:#e2e8f0;--good:#059669;--warn:#ea580c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,sans-serif}.screen{min-height:100vh;padding:12px 16px 160px}.topbar{align-items:center;display:flex;gap:12px;margin-bottom:16px;padding-top:calc(8px + env(safe-area-inset-top,0px))}.back{color:var(--p);font-size:20px;text-decoration:none}.titles{flex:1;min-width:0}.store{color:var(--muted);font-size:11px;font-weight:600;letter-spacing:.4px;overflow:hidden;text-overflow:ellipsis;text-transform:uppercase;white-space:nowrap}h1{font-size:22px;margin:2px 0}.kpis{display:grid;gap:8px;grid-template-columns:repeat(2,1fr);margin-bottom:14px}.kpi{background:#fff;border:1px solid var(--border);border-radius:12px;padding:12px}.kpi b{display:block;font-size:18px;margin-top:4px}.kpi span{color:var(--muted);font-size:11px}.list{display:grid;gap:10px}.card{background:#fff;border:1px solid var(--border);border-radius:14px;color:var(--text);padding:14px;text-decoration:none}.head{display:flex;gap:10px}.name{flex:1;font-size:15px;font-weight:700}.balance{color:var(--warn);font-size:15px;font-weight:700}.sub{color:var(--muted);font-size:12px;line-height:1.45;margin-top:5px}.tag{background:#d1fae5;border-radius:99px;color:#047857;font-size:11px;font-weight:700;padding:4px 8px}.tag.completed{background:#e2e8f0;color:#475569}.empty{background:#fff;border:1px dashed var(--border);border-radius:14px;color:var(--muted);padding:30px 15px;text-align:center}</style></head><body><main class="screen"><header class="topbar"><a class="back" href="<?= base_url('mobile/more'); ?>"><i class="fa fa-chevron-left"></i></a><div class="titles"><div class="store"><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?></div><h1>Installment Plans</h1></div></header><section class="kpis"><div class="kpi"><span>Total plans</span><b><?= number_format($stats['total_plans']); ?></b></div><div class="kpi"><span>Active plans</span><b><?= number_format($stats['active_plans']); ?></b></div><div class="kpi"><span>Outstanding</span><b><?= $this->currency(store_number_format($stats['total_outstanding'])); ?></b></div><div class="kpi"><span>Overdue payments</span><b><?= number_format($stats['overdue_count']); ?></b></div></section><section class="list"><?php foreach($plans as $plan): $balance=(float)$plan->total_amount-(float)$plan->total_paid; ?><a class="card" href="<?= base_url('mobile/installments/'.(int)$plan->id); ?>"><div class="head"><div class="name"><?= htmlspecialchars($plan->customer_name ?: 'Customer'); ?><div class="sub"><?= htmlspecialchars($plan->plan_code); ?> · <?= (int)$plan->installment_count; ?> × <?= $this->currency(store_number_format($plan->installment_amount)); ?></div></div><div class="balance"><?= $this->currency(store_number_format($balance)); ?></div></div><div class="sub" style="margin-top:10px"><span class="tag <?= $plan->status==='completed'?'completed':''; ?>"><?= htmlspecialchars(ucfirst($plan->status)); ?></span> First due <?= show_date($plan->first_due_date); ?></div></a><?php endforeach; ?><?php if(empty($plans)): ?><div class="empty"><i class="fa fa-calendar-check-o fa-2x"></i><p>No installment plans yet.</p></div><?php endif; ?></section></main><?php $this->load->view('mobile/bottom_nav',['active'=>'more']); ?><?php $this->load->view('mobile/mp_alert'); ?><?php $this->load->view('mobile/chat'); ?></body></html>
